var SUPPLIER_LPP_FIELDS = [
	"custom_last_purchase_price",
	"custom_last_purchase_po",
	"custom_last_purchase_date",
	"custom_last_purchase_currency",
	"custom_last_purchase_uom",
	"custom_price_difference",
	"custom_price_difference_percent",
];

function supplierLppValuesEqual(currentValue, resolvedValue) {
	const currentBlank = currentValue === null || currentValue === undefined || currentValue === "";
	const resolvedBlank = resolvedValue === null || resolvedValue === undefined || resolvedValue === "";
	if (currentBlank || resolvedBlank) return currentBlank && resolvedBlank;
	return currentValue === resolvedValue || String(currentValue) === String(resolvedValue);
}

function setSupplierLppValueIfChanged(row, fieldname, value) {
	if (supplierLppValuesEqual(row[fieldname], value)) return false;
	frappe.model.set_value(row.doctype, row.name, fieldname, value);
	return true;
}

function calculateSupplierQuotationVariance(row) {
	const currentRate = flt(row.rate || 0);
	const lpp = flt(row.custom_last_purchase_price || 0);
	if (currentRate <= 0 || lpp <= 0) {
		setSupplierLppValueIfChanged(row, "custom_price_difference", null);
		setSupplierLppValueIfChanged(row, "custom_price_difference_percent", null);
		return;
	}

	const difference = currentRate - lpp;
	setSupplierLppValueIfChanged(row, "custom_price_difference", difference);
	setSupplierLppValueIfChanged(row, "custom_price_difference_percent", (difference / lpp) * 100);
}

function getSupplierQuotationItemPriceContext(frm, row) {
	return JSON.stringify([
		frm.doc.supplier || "",
		frm.doc.currency || "",
		row.item_code || "",
		row.uom || row.stock_uom || "",
	]);
}

function clearSupplierNeutralPriceListDefault(frm, row) {
	if (!row.__islocal) return false;
	const context = getSupplierQuotationItemPriceContext(frm, row);
	if (row.__calcoCurrentPriceCheckedContext === context) return false;
	row.__calcoCurrentPriceCheckedContext = context;

	const currentRate = flt(row.rate || 0);
	const priceListRate = flt(row.price_list_rate || 0);
	if (currentRate <= 0 || priceListRate <= 0) return false;
	if (Math.abs(currentRate - priceListRate) > 0.000001) return false;

	setSupplierLppValueIfChanged(row, "rate", null);
	return true;
}

function invalidateSupplierQuotationCurrentPrices(frm) {
	(frm.doc.items || []).forEach((row) => {
		row.__calcoCurrentPriceCheckedContext = null;
		setSupplierLppValueIfChanged(row, "rate", null);
		setSupplierLppValueIfChanged(row, "custom_price_difference", null);
		setSupplierLppValueIfChanged(row, "custom_price_difference_percent", null);
	});
}

function applySupplierQuotationLppResponse(frm, rows) {
	const byKey = {};
	(rows || []).forEach((row) => {
		byKey[row.row_key] = row;
		byKey[`idx:${row.idx}`] = row;
	});

	(frm.doc.items || []).forEach((row) => {
		const resolved = byKey[row.name] || byKey["idx:" + row.idx];
		if (!resolved) return;
		SUPPLIER_LPP_FIELDS.slice(0, 5).forEach((fieldname) => {
			setSupplierLppValueIfChanged(row, fieldname, resolved[fieldname.replace("custom_", "")]);
		});
		if (clearSupplierNeutralPriceListDefault(frm, row)) {
			setSupplierLppValueIfChanged(row, "custom_price_difference", null);
			setSupplierLppValueIfChanged(row, "custom_price_difference_percent", null);
		} else {
			setSupplierLppValueIfChanged(row, "custom_price_difference", resolved.price_difference);
			setSupplierLppValueIfChanged(
				row,
				"custom_price_difference_percent",
				resolved.price_difference_percent
			);
		}
	});

	const missing = (rows || []).filter((row) => row.item_code && !row.comparable).map((row) => row.item_code);
	if (missing.length && frm.doc.supplier && frm.doc.currency) {
		frm.dashboard.set_headline_alert(
			__(
				"Last Purchase Price not available for this supplier: {0}",
				[Array.from(new Set(missing)).join(", ")]
			),
			"orange"
		);
		frm.__calcoLppHeadlineVisible = true;
	} else if (frm.__calcoLppHeadlineVisible) {
		frm.dashboard.clear_headline();
		frm.__calcoLppHeadlineVisible = false;
	}
}

function getSupplierQuotationLppContext(frm) {
	const itemContext = (frm.doc.items || []).map((row) => [row.item_code || "", row.uom || row.stock_uom || ""]);
	return JSON.stringify([frm.doc.supplier || "", frm.doc.currency || "", itemContext]);
}

function refreshSupplierQuotationLpp(frm, expectedContext) {
	if (frm.doc.docstatus !== 0) return;
	const requestContext = expectedContext || getSupplierQuotationLppContext(frm);
	if (requestContext !== getSupplierQuotationLppContext(frm)) return;
	const requestVersion = (frm.__calcoLppRequestVersion || 0) + 1;
	frm.__calcoLppRequestVersion = requestVersion;
	frm.__calcoLppPendingContext = requestContext;
	if (!frm.doc.supplier || !frm.doc.currency) {
		const emptyRows = (frm.doc.items || []).map((row) => ({
			row_key: row.name,
			idx: row.idx,
			item_code: row.item_code,
			comparable: false,
			last_purchase_price: null,
			last_purchase_po: null,
			last_purchase_date: null,
			last_purchase_currency: null,
			last_purchase_uom: null,
			price_difference: null,
			price_difference_percent: null,
		}));
		applySupplierQuotationLppResponse(frm, emptyRows);
		frm.__calcoLppResolvedContext = requestContext;
		frm.__calcoLppPendingContext = null;
		return;
	}
	frappe.call({
		method: "calco_erp.calco_purchase.supplier_last_purchase_price.preview_supplier_quotation_lpp",
		args: { doc: frm.doc },
		freeze: false,
		callback: ({ message }) => {
			if (frm.doc.docstatus !== 0) return;
			if (requestVersion !== frm.__calcoLppRequestVersion) return;
			if (requestContext !== getSupplierQuotationLppContext(frm)) return;
			applySupplierQuotationLppResponse(frm, message?.rows || []);
			frm.__calcoLppResolvedContext = requestContext;
			frm.__calcoLppPendingContext = null;
		},
		error: () => {
			if (requestVersion === frm.__calcoLppRequestVersion) frm.__calcoLppPendingContext = null;
		},
	});
}

function queueSupplierQuotationLppRefresh(frm) {
	if (frm.doc.docstatus !== 0) return;
	const context = getSupplierQuotationLppContext(frm);
	if (context === frm.__calcoLppResolvedContext || context === frm.__calcoLppPendingContext) return;
	clearTimeout(frm.__calcoLppRefreshTimer);
	frm.__calcoLppRefreshTimer = setTimeout(() => refreshSupplierQuotationLpp(frm, context), 250);
}

frappe.ui.form.on("Supplier Quotation", {
	refresh(frm) {
		frm.fields_dict.items.grid.update_docfield_property("rate", "label", __("Current Price"));
		if (frm.__calcoCurrentPriceSupplier === undefined) {
			frm.__calcoCurrentPriceSupplier = frm.doc.supplier || "";
		}
		if (frm.__calcoCurrentPriceCurrency === undefined) {
			frm.__calcoCurrentPriceCurrency = frm.doc.currency || "";
		}
		if (frm.doc.docstatus === 0) queueSupplierQuotationLppRefresh(frm);
	},
	supplier(frm) {
		const supplier = frm.doc.supplier || "";
		if (
			frm.__calcoCurrentPriceSupplier !== undefined &&
			frm.__calcoCurrentPriceSupplier !== supplier
		) {
			invalidateSupplierQuotationCurrentPrices(frm);
		}
		frm.__calcoCurrentPriceSupplier = supplier;
		queueSupplierQuotationLppRefresh(frm);
	},
	currency(frm) {
		const currency = frm.doc.currency || "";
		if (
			frm.__calcoCurrentPriceCurrency !== undefined &&
			frm.__calcoCurrentPriceCurrency !== currency
		) {
			invalidateSupplierQuotationCurrentPrices(frm);
		}
		frm.__calcoCurrentPriceCurrency = currency;
		queueSupplierQuotationLppRefresh(frm);
	},
});

frappe.ui.form.on("Supplier Quotation Item", {
	item_code(frm, cdt, cdn) {
		const row = locals[cdt][cdn];
		row.__calcoCurrentPriceCheckedContext = null;
		setSupplierLppValueIfChanged(row, "rate", null);
		queueSupplierQuotationLppRefresh(frm);
	},
	uom(frm, cdt, cdn) {
		const row = locals[cdt][cdn];
		row.__calcoCurrentPriceCheckedContext = null;
		setSupplierLppValueIfChanged(row, "rate", null);
		queueSupplierQuotationLppRefresh(frm);
	},
	items_add(frm) {
		queueSupplierQuotationLppRefresh(frm);
	},
	items_remove(frm) {
		queueSupplierQuotationLppRefresh(frm);
	},
	rate(frm, cdt, cdn) {
		calculateSupplierQuotationVariance(locals[cdt][cdn]);
	},
});

(function () {
  const STATUS_FIELD = "custom_material_readiness_status";
  const LINK_FIELD = "custom_material_readiness_check";
  const HTML_FIELD = "custom_material_readiness_summary";
  const FALLBACK_CLASS = "calco-work-order-mrc-summary";

  function getSummaryWrapper(frm) {
    if (frm.fields_dict[HTML_FIELD] && frm.fields_dict[HTML_FIELD].$wrapper && frm.fields_dict[HTML_FIELD].$wrapper.is(":visible")) {
      return frm.fields_dict[HTML_FIELD].$wrapper;
    }

    const gridWrapper = frm.fields_dict.required_items && frm.fields_dict.required_items.grid && frm.fields_dict.required_items.grid.wrapper
      ? $(frm.fields_dict.required_items.grid.wrapper)
      : null;
    if (!gridWrapper || !gridWrapper.length) {
      return null;
    }

    let wrapper = gridWrapper.siblings(`.${FALLBACK_CLASS}`);
    if (!wrapper.length) {
      wrapper = $(`<div class="${FALLBACK_CLASS}" style="margin-top:16px;"></div>`);
      wrapper.insertAfter(gridWrapper);
    }
    return wrapper;
  }

  function setSummary(frm, context) {
    const wrapper = getSummaryWrapper(frm);
    if (!wrapper) {
      return;
    }

    const badgeColor = context.ready_status === "Ready"
      ? "#2e7d32"
      : context.linked_check
        ? "#ef6c00"
        : "#c62828";

    const linkedHtml = context.linked_check
      ? `<div style="margin-top:8px;"><a href="#" class="calco-open-mrc">${frappe.utils.escape_html(context.linked_check)}</a></div>`
      : `<div style="margin-top:8px; color:var(--text-muted);">${__("No Material Readiness Check linked yet.")}</div>`;

    const shortageHtml = context.shortage_summary
      ? `<div style="margin-top:10px; font-size:12px; white-space:pre-wrap; color:var(--text-muted);">${frappe.utils.escape_html(context.shortage_summary)}</div>`
      : "";

    wrapper.html(`
      <div style="padding:12px 14px; border:1px solid var(--border-color); border-radius:12px; background:rgba(248,250,252,0.9);">
        <div style="display:flex; align-items:center; gap:8px; flex-wrap:wrap;">
          <span style="display:inline-flex; padding:4px 8px; border-radius:999px; font-size:11px; font-weight:700; color:white; background:${badgeColor};">
            ${frappe.utils.escape_html(context.ready_status || "Not Started")}
          </span>
          <span style="font-size:12px; color:var(--text-muted);">${frappe.utils.escape_html(context.message || "")}</span>
        </div>
        ${linkedHtml}
        ${shortageHtml}
      </div>
    `);

    wrapper.find(".calco-open-mrc").on("click", (event) => {
      event.preventDefault();
      if (context.linked_check) {
        frappe.set_route("Form", "Material Readiness Check", context.linked_check);
      }
    });
  }

  async function refreshReadiness(frm) {
    if (frm.is_new()) {
      frm.set_intro(__("Save the Work Order to create Material Readiness Check."), "blue");
      frm.set_value(STATUS_FIELD, "");
      frm.set_value(LINK_FIELD, "");
      setSummary(frm, { ready_status: "Not Started", message: __("Save the Work Order to create Material Readiness Check.") });
      return;
    }

    const response = await frappe.call({
      method: "calco_erp.calco_production.material_readiness_work_order.get_work_order_material_readiness_context",
      args: { work_order: frm.doc.name },
      freeze: false,
    });

    const context = response.message || {};
    frm.__material_readiness_context = context;
    await frm.set_value(STATUS_FIELD, context.ready_status || "");
    await frm.set_value(LINK_FIELD, context.linked_check || "");
    setSummary(frm, context);

    if (context.ready_status === "Ready") {
      frm.set_intro(__("Material Readiness Check {0} is Ready.", [context.linked_check || "-"]), "green");
    } else if (context.linked_check) {
      frm.set_intro(__("Material Readiness Check {0} is currently {1}.", [context.linked_check, context.ready_status || __("Draft")]), "orange");
    } else {
      frm.set_intro(__("No Material Readiness Check exists yet for this Work Order."), "red");
    }

    frm.remove_custom_button(__("Create Material Readiness Check"), __("Material Readiness"));
    frm.remove_custom_button(__("Open Material Readiness Check"), __("Material Readiness"));

    if (context.linked_check) {
      frm.add_custom_button(__("Open Material Readiness Check"), () => {
        frappe.set_route("Form", "Material Readiness Check", context.linked_check);
      }, __("Material Readiness"));
    } else {
      frm.add_custom_button(__("Create Material Readiness Check"), async () => {
        const createResponse = await frappe.call({
          method: "calco_erp.calco_production.material_readiness_work_order.create_material_readiness_check",
          args: { work_order: frm.doc.name },
          freeze: true,
        });
        const doc = createResponse.message || {};
        if (doc.name) {
          frappe.set_route("Form", "Material Readiness Check", doc.name);
        }
      }, __("Material Readiness"));
    }
  }

  frappe.ui.form.on("Work Order", {
    refresh(frm) {
      refreshReadiness(frm).catch((error) => {
        frappe.msgprint(error.message || __("Unable to load Material Readiness context."));
      });
    },
  });
})();

const GOVERNANCE_ASSET_PATH = "/assets/calco_erp/js/master_data_governance_journey.js";
const GOVERNANCE_HOST_CLASS = "calco-governance-journey-host";
const GOVERNANCE_METHOD = "calco_erp.calco_purchase.master_data_governance_journey.get_new_supplier_request_tracker";

function findVisibleSectionNode(frm, titleText) {
    const root = $(frm.wrapper || document.body);
    const candidates = root.find(".section-head, .form-section .section-head, .section-head .section-title, .section-label, .form-page .section-head");

    for (const node of candidates.toArray()) {
        const element = $(node);
        const text = (element.text() || "").trim();
        if (!element.is(":visible") || text !== titleText) {
            continue;
        }

        const section = element.closest(".form-section");
        if (section.length) {
            return section;
        }

        const column = element.closest(".section-body, .frappe-control, .form-column, .row");
        if (column.length) {
            return column;
        }

        return element;
    }

    return $();
}

function getGovernanceDebugAnchor(frm) {
    const root = $(frm.wrapper || document.body);
    let wrapper = root.find(`.${GOVERNANCE_HOST_CLASS}`).first();
    if (wrapper.length) {
        return wrapper;
    }

    const journeySection = findVisibleSectionNode(frm, "Request Journey");
    if (journeySection.length) {
        wrapper = $(`<div class="${GOVERNANCE_HOST_CLASS}"></div>`);
        wrapper.insertAfter(journeySection);
        return wrapper;
    }

    const requestSummarySection = findVisibleSectionNode(frm, "Request Summary");
    if (requestSummarySection.length) {
        wrapper = $(`<div class="${GOVERNANCE_HOST_CLASS}"></div>`);
        wrapper.insertBefore(requestSummarySection);
        return wrapper;
    }

    const formLayout = root.find(".form-layout, .layout-main-section, .page-form").first();
    if (formLayout.length) {
        wrapper = $(`<div class="${GOVERNANCE_HOST_CLASS}"></div>`);
        formLayout.prepend(wrapper);
        return wrapper;
    }

    return null;
}

function clearGovernanceMount(frm) {
    const wrapper = getGovernanceDebugAnchor(frm);
    if (!wrapper) {
        return;
    }
    wrapper.empty();
}

function getGovernanceObject() {
    return window.calco_erp && window.calco_erp.master_data_governance;
}

function getGovernanceRenderFunction() {
    return window.renderMasterDataJourney;
}

function loadGovernanceAsset() {
    return new Promise((resolve) => {
        frappe.require(GOVERNANCE_ASSET_PATH, () => {
            resolve(getGovernanceRenderFunction() || getGovernanceObject() || null);
        });
    });
}

async function fetchJourneyPayload(frm) {
    const response = await frappe.call({
        method: GOVERNANCE_METHOD,
        args: { name: frm.doc.name },
        freeze: false,
    });
    return response.message || {};
}

function renderStageCards(frm, payload) {
    const wrapper = getGovernanceDebugAnchor(frm);
    if (!wrapper) {
        return;
    }

    const stages = Array.isArray(payload.stages) ? payload.stages : [];
    if (!stages.length) {
        wrapper.html(`<div style="font-size:12px; color: var(--text-muted);">No stages available.</div>`);
        return;
    }

    const colorMap = {
        "Completed": "#2e7d32",
        "In Progress": "#1565c0",
        "Rejected": "#c62828",
        "Stopped": "#64748b",
        "Not Started": "#94a3b8",
    };

    wrapper.html(`
        <div style="display:flex; gap:12px; overflow-x:auto; padding-bottom:4px;">
            ${stages.map((stage) => `
                <div style="min-width:210px; border:1px solid var(--border-color); border-radius:14px; background: var(--fg-color); padding:14px 16px; box-shadow: inset 0 4px 0 ${colorMap[stage.status] || '#94a3b8'};">
                    <div style="font-size:13px; font-weight:700; margin-bottom:8px;">${frappe.utils.escape_html(stage.label || '')}</div>
                    <div style="display:inline-flex; padding:4px 8px; border-radius:999px; font-size:11px; font-weight:700; margin-bottom:8px; background: rgba(15,23,42,0.06);">${frappe.utils.escape_html(stage.status || '')}</div>
                    <div style="font-size:11px; text-transform:uppercase; color: var(--text-muted); margin-bottom:8px;">${frappe.utils.escape_html(stage.owner_role || '')}</div>
                    <div style="font-size:12px; line-height:1.45; color: var(--text-muted);">${frappe.utils.escape_html(stage.summary || '')}</div>
                </div>
            `).join('')}
        </div>
    `);
}

frappe.ui.form.on("New Supplier Request", {
    async refresh(frm) {
        let governance = getGovernanceRenderFunction() || getGovernanceObject();
        clearGovernanceMount(frm);

        if (!governance) {
            governance = await loadGovernanceAsset();
        }

        if (window.syncMasterDataJourneyState) {
            window.syncMasterDataJourneyState(frm);
        } else if (governance && governance.syncMainFormState) {
            governance.syncMainFormState(frm);
        }

        const payload = await fetchJourneyPayload(frm);
        frm.__governance_journey_data = payload || {};
        renderStageCards(frm, payload || {});

        if (typeof window.renderMasterDataJourney === "function") {
            await window.renderMasterDataJourney(frm, payload);
            return;
        }
    },
    async onload_post_render(frm) {
        const governance = getGovernanceRenderFunction() || getGovernanceObject() || await loadGovernanceAsset();
        if (typeof window.renderMasterDataJourney === "function" && frm.__governance_journey_data) {
            await window.renderMasterDataJourney(frm, frm.__governance_journey_data);
        }
    },
    status(frm) {
        const governance = getGovernanceObject();
        if (window.syncMasterDataJourneyState) {
            window.syncMasterDataJourneyState(frm);
        } else if (governance && governance.syncMainFormState) {
            governance.syncMainFormState(frm);
        }
    },
});

